import type { ReadinessBaseline, ReadinessCandidate } from "./readiness-export"

const OUTPUT_PATH = "data/scanner-catalog-coverage/2026-08-26/phase1a-existing-ledger.json"

export const PHASE_1A_TARGETS = {
