    research_only: true
    note: string
  }
  targets: typeof PHASE_1B_TARGETS
  reconciliation: {
    selected_products: number
    by_category: Record<
      Phase1bCategory,
      { target: number; selected: number; pilot: number; new_product: number }
    >
  }
  rows: Phase1bRow[]
  content_fingerprint: string
}

export type Phase1PilotManifest = {
  schema_version: "scanner-phase1-pilot-manifest-v1"
  generated_at: string
  source: {
    phase1a_content_fingerprint: string
    phase1b_content_fingerprint: string
    research_only: true
    note: string
  }
  totals: {
    existing_products: 20
    new_products: 5
    total_products: 25
    existing_canonical_gtins: 22
    new_canonical_gtins: 5
    unique_canonical_gtins: 27
  }
  existing: Array<{
    product_id: string
    category_key: string
    identity: Phase1aRow["identity"]
    packages: NonNullable<Phase1aRow["pilot_gtin_evidence"]>["packages"]
  }>
  new: Array<{
    candidate_id: string
    category_key: Phase1bCategory
    identity: Phase1bRow["identity"]
    package: Phase1bRow["package"]
    source_urls: string[]
  }>
  content_fingerprint: string
}

function stable(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stable)
  if (value && typeof value === "object")
    return Object.fromEntries(
      Object.keys(value as Record<string, unknown>)
        .sort()
        .map((key) => [key, stable((value as Record<string, unknown>)[key])]),
    )
  return value
}

export function fingerprint(content: unknown): string {
  return createHash("sha256")
    .update(JSON.stringify(stable(content)))
    .digest("hex")
}

function normalizeIdentity(brand: string, productLine: string | null, name: string): string {
  return [brand, productLine ?? "", name]
    .join(" ")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ")
}

function asString(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value.trim() : null
}
function arrayOfStrings(value: unknown): string[] {
  return Array.isArray(value)
    ? value.map(asString).filter((item): item is string => item !== null)
    : []
}

function sourcePdpUrls(candidate: Candidate): string[] {
  const direct = asString(candidate.source_pdp_url)
  const nested = Array.isArray(candidate.sources)
    ? candidate.sources.flatMap((item) => asString((item as Record<string, unknown>).url) ?? [])
    : []
  return [...new Set([...(direct ? [direct] : []), ...nested])].filter(isExactRetailerPdp).sort()
}

function retailerNames(candidate: Candidate): string[] {
  const direct = arrayOfStrings(candidate.retailers)
  const nested = Array.isArray(candidate.sources)
    ? candidate.sources.flatMap(
        (item) => asString((item as Record<string, unknown>).retailer) ?? [],
      )
    : []
  return [...new Set([...direct, ...nested])].map((item) => item.toLowerCase()).sort()
}

export function isExactRetailerPdp(url: string): boolean {
  try {
    const parsed = new URL(url)
    const host = parsed.hostname.toLowerCase()
    const path = parsed.pathname.toLowerCase()
    if (host.endsWith("dm.de")) return /^\/p\/d\/\d+\//.test(path) || /-p\d+\.html$/.test(path)
    if (host.endsWith("rossmann.de")) return /\/p\/\d+$/.test(path)
    if (host.endsWith("mueller.de")) return /^\/p\//.test(path)
    return true
  } catch {
    return false
  }
}

function categoryOf(candidate: Candidate): Phase1bCategory | null {
  return asString(candidate.category) as Phase1bCategory | null
}
function statusOf(candidate: Candidate): string | null {
  return (
    asString((candidate.reconciliation as Candidate | undefined)?.status) ??
    asString(candidate.reconciliation_status)
  )
}
function categoryFitOf(candidate: Candidate): string | null {
  return (
    asString((candidate.reconciliation_review as Candidate | undefined)?.category_fit_triage) ??
    "accepted_for_category_contract"
  )
}
function ownershipOf(candidate: Candidate): Candidate {
  return (
    ((candidate.reconciliation as Candidate | undefined)?.gtin_ownership as
      | Candidate
      | undefined) ??
    ((candidate.reconciliation_review as Candidate | undefined)?.gtin_ownership as
      | Candidate
      | undefined) ??
    {}
  )
}
function canonicalGtinOf(candidate: Candidate): string | null {
  const direct = asString(candidate.canonical_gtin14)
  const ownership = asString(ownershipOf(candidate).canonical_gtin14)
  const raw = asString(candidate.gtin) ?? asString(ownershipOf(candidate).gtin)
  const supplied = direct ?? ownership ?? raw
  if (!supplied) return null
  const canonical = canonicalizeGtin(supplied)
  if (!canonical) throw new Error(`phase1b_invalid_gtin:${String(candidate.candidate_id)}`)
  return canonical
}
function rawGtinOf(candidate: Candidate): string | null {
  return (
    asString(candidate.gtin) ??
    asString((candidate.gtin_evidence as Candidate | undefined)?.value_seen) ??
    asString(ownershipOf(candidate).gtin)
  )
}
function confidenceOf(candidate: Candidate): string | null {
  return (
    asString((candidate.reconciliation as Candidate | undefined)?.match_confidence) ??
    asString((candidate.reconciliation_review as Candidate | undefined)?.confidence)
  )
}
function priorityRankOf(candidate: Candidate): number {
  return typeof candidate.priority_rank === "number"
    ? candidate.priority_rank
    : Number.MAX_SAFE_INTEGER
}

function isEligible(candidate: Candidate): boolean {
  const urls = sourcePdpUrls(candidate)
  return (
    statusOf(candidate) === "new_candidate_confirmed" &&
    categoryFitOf(candidate) === "accepted_for_category_contract" &&
    urls.length > 0
  )
}

function candidateComparator(
  left: { candidate: Candidate; source: CandidateSource },
  right: { candidate: Candidate; source: CandidateSource },
): number {
  const sourceRank = (source: CandidateSource) => (source === "retailer-specialist" ? 0 : 1)
  const a = sourceRank(left.source) - sourceRank(right.source)
  if (a !== 0) return a
  const b = priorityRankOf(left.candidate) - priorityRankOf(right.candidate)
  if (b !== 0) return b
  const c =
    Number(canonicalGtinOf(right.candidate) !== null) -
    Number(canonicalGtinOf(left.candidate) !== null)
  if (c !== 0) return c
  const d = retailerNames(right.candidate).length - retailerNames(left.candidate).length
  if (d !== 0) return d
  return String(left.candidate.candidate_id).localeCompare(String(right.candidate.candidate_id))
}

function toRow(
  entry: { candidate: Candidate; source: CandidateSource },
  category: Phase1bCategory,
  inclusionRank: number,
  pilotIds: Set<string>,
): Phase1bRow {
  const candidate = entry.candidate
  const canonicalBrand = asString(candidate.canonical_brand)
  const cleanName = asString(candidate.clean_name)
  const productLine = asString(candidate.product_line)
  const candidateId = asString(candidate.candidate_id)
  if (!candidateId || !canonicalBrand || !cleanName)
    throw new Error(`phase1b_identity_incomplete:${candidateId ?? "unknown"}`)
  const canonicalGtin14 = canonicalGtinOf(candidate)
  return {
    candidate_id: candidateId,
    category_key: category,
    inclusion_rank: inclusionRank,
    wave: pilotIds.has(candidateId) ? "pilot" : "new_product",
    identity: {
      canonical_brand: canonicalBrand,
      product_line: productLine,
      clean_name: cleanName,
      normalized_identity: normalizeIdentity(canonicalBrand, productLine, cleanName),
    },
    package: {
      size: asString(candidate.package_size) ?? "not_provided",
      gtin: rawGtinOf(candidate),
      canonical_gtin14: canonicalGtin14,
    },
    sources: {
      pdp_urls: sourcePdpUrls(candidate),
      retailers: retailerNames(candidate),
      source_priority: entry.source,
    },
    popularity: {
      priority_rank: priorityRankOf(candidate),
      visibility_signal:
        asString(candidate.visibility_signal) ??
        asString((candidate.sources as Candidate[] | undefined)?.[0]?.visibility_signal) ??
        "not_provided",
      priority_rationale: asString(candidate.priority_rationale),
    },
    reconciliation: {
      status: "new_candidate_confirmed",
      category_fit: "accepted_for_category_contract",
      confidence: confidenceOf(candidate),
      gtin_ownership_state: asString(ownershipOf(candidate).status) ?? "not_provided",
      source_payload: candidate,
    },
    catalog_readiness: {
      research_only: true,
      catalog_intake_ready: false,
      scan_result_ready: false,
      blockers: [
        "full_product_intake_evidence_required",
        "ingredient_classification_required",
        "human_review_required",
        "catalog_publish_not_authorized",
      ],
    },
  }
}

function assertUnique(rows: Phase1bRow[]) {
  const seen = new Map<string, string>()
  for (const row of rows) {
    for (const [kind, value] of [
      ["candidate_id", row.candidate_id],
      ["normalized_identity", row.identity.normalized_identity],
      ["canonical_gtin14", row.package.canonical_gtin14],
    ] as const) {
      if (!value) continue
      const key = `${kind}:${value}`
      if (seen.has(key))
        throw new Error(`phase1b_duplicate_${kind}:${value}:${seen.get(key)}:${row.candidate_id}`)
      seen.set(key, row.candidate_id)
    }
    for (const sourcePdpUrl of row.sources.pdp_urls) {
      const key = `source_pdp_url:${sourcePdpUrl}`
      if (seen.has(key))
        throw new Error(
          `phase1b_duplicate_source_pdp_url:${sourcePdpUrl}:${seen.get(key)}:${row.candidate_id}`,
        )
      seen.set(key, row.candidate_id)
    }
  }
}

function rowUniqueKeys(row: Phase1bRow): string[] {
  return [
    `candidate_id:${row.candidate_id}`,
    `normalized_identity:${row.identity.normalized_identity}`,
    ...row.sources.pdp_urls.map((url) => `source_pdp_url:${url}`),
    ...(row.package.canonical_gtin14 ? [`canonical_gtin14:${row.package.canonical_gtin14}`] : []),
  ]
}

function canSelect(row: Phase1bRow, selectedKeys: Set<string>): boolean {
  return rowUniqueKeys(row).every((key) => !selectedKeys.has(key))
}

function retain(row: Phase1bRow, selectedKeys: Set<string>) {
  for (const key of rowUniqueKeys(row)) selectedKeys.add(key)
}

export function buildPhase1bLedger(input: {
  core: { content_fingerprint: string; candidates: Candidate[] }
  specialist: { content_fingerprint: string; candidates: Candidate[] }
  pilotResearch: NewPilotResearch
  generatedAt: string
}): Phase1bLedger {
  const pilotIds = new Set(input.pilotResearch.products.map((product) => product.candidate_id))
  if (pilotIds.size !== 5) throw new Error(`phase1b_pilot_expected_5_products:${pilotIds.size}`)
  const all = [
    ...input.core.candidates.map((candidate) => ({ candidate, source: "retailer-core" as const })),
    ...input.specialist.candidates.map((candidate) => ({
      candidate,
      source: "retailer-specialist" as const,
    })),
  ]
  const byId = new Map(all.map((entry) => [String(entry.candidate.candidate_id), entry]))
  for (const seed of input.pilotResearch.products) {
    const candidate = byId.get(seed.candidate_id)
    if (
      !candidate ||
      !isEligible(candidate.candidate) ||
      categoryOf(candidate.candidate) !== seed.category_key
    )
      throw new Error(`phase1b_pilot_not_eligible:${seed.candidate_id}`)
    if (canonicalGtinOf(candidate.candidate) !== seed.canonical_gtin14)
      throw new Error(`phase1b_pilot_gtin_drift:${seed.candidate_id}`)
  }
  const entriesByCategory = new Map(
    (Object.keys(PHASE_1B_TARGETS) as Phase1bCategory[]).map((category) => [
      category,
      {
        pilot: all
          .filter(
            (entry) =>
              categoryOf(entry.candidate) === category &&
              pilotIds.has(String(entry.candidate.candidate_id)),
          )
          .sort(candidateComparator),
        eligible: all
          .filter(
            (entry) =>
              categoryOf(entry.candidate) === category &&
              isEligible(entry.candidate) &&
              !pilotIds.has(String(entry.candidate.candidate_id)),
          )
          .sort(candidateComparator),
      },
    ]),
  )
  const selectedRows = new Map<Phase1bCategory, Phase1bRow[]>()
  const selectedKeys = new Set<string>()
  for (const category of Object.keys(PHASE_1B_TARGETS) as Phase1bCategory[]) {
    const pilot = entriesByCategory.get(category)!.pilot
    if (pilot.length > PHASE_1B_TARGETS[category])
      throw new Error(`phase1b_pilot_exceeds_target:${category}`)
    const retained = pilot.map((entry, index) => toRow(entry, category, index + 1, pilotIds))
    for (const row of retained) {
      if (!canSelect(row, selectedKeys))
        throw new Error(`phase1b_pilot_conflict:${row.candidate_id}`)
      retain(row, selectedKeys)
    }
    selectedRows.set(category, retained)
  }
  const categoryOrder = (Object.keys(PHASE_1B_TARGETS) as Phase1bCategory[]).sort((left, right) => {
    const leftSurplus =
      entriesByCategory.get(left)!.eligible.length +
      entriesByCategory.get(left)!.pilot.length -
      PHASE_1B_TARGETS[left]
    const rightSurplus =
      entriesByCategory.get(right)!.eligible.length +
      entriesByCategory.get(right)!.pilot.length -
      PHASE_1B_TARGETS[right]
    return leftSurplus - rightSurplus || left.localeCompare(right)
  })
  for (const category of categoryOrder) {
    const target = PHASE_1B_TARGETS[category]
    const chosen = selectedRows.get(category)!
    for (const entry of entriesByCategory.get(category)!.eligible) {
      if (chosen.length === target) break
      const row = toRow(entry, category, chosen.length + 1, pilotIds)
      if (!canSelect(row, selectedKeys)) continue
      chosen.push(row)
      retain(row, selectedKeys)
    }
    if (chosen.length !== target)
      throw new Error(`phase1b_target_shortage:${category}:${chosen.length}:${target}`)
  }
  const rows = [...selectedRows.values()].flat()
  rows.sort((a, b) =>
    `${a.category_key}\u0000${String(a.inclusion_rank).padStart(3, "0")}\u0000${a.candidate_id}`.localeCompare(
      `${b.category_key}\u0000${String(b.inclusion_rank).padStart(3, "0")}\u0000${b.candidate_id}`,
    ),
  )
  assertUnique(rows)
  if (rows.length !== 54) throw new Error(`phase1b_expected_54_rows:${rows.length}`)
  const reconciliation = {
    selected_products: rows.length,
    by_category: Object.fromEntries(
      (Object.keys(PHASE_1B_TARGETS) as Phase1bCategory[]).map((category) => {
        const selected = rows.filter((row) => row.category_key === category)
        return [
          category,
          {
            target: PHASE_1B_TARGETS[category],
            selected: selected.length,
            pilot: selected.filter((row) => row.wave === "pilot").length,
            new_product: selected.filter((row) => row.wave === "new_product").length,
          },
        ]
      }),
    ) as Phase1bLedger["reconciliation"]["by_category"],
  }
  const content = {
    schema_version: "scanner-phase1b-new-ledger-v1" as const,
    source: {
      core_content_fingerprint: input.core.content_fingerprint,
      specialist_content_fingerprint: input.specialist.content_fingerprint,
      pilot_research_id: input.pilotResearch.research_id,
      research_only: true as const,
      note: "All selected rows are externally evidenced, reconciled new candidates only. They remain research-only and require full Product Intake evidence, ingredient classification, human review, and authorized publication before any scanner result may use them.",
    },
    targets: PHASE_1B_TARGETS,
    reconciliation,
    rows,
  }
  return { generated_at: input.generatedAt, ...content, content_fingerprint: fingerprint(content) }
}

export function buildPilotManifest(input: {
  phase1a: Phase1aLedger
  phase1b: Phase1bLedger
  generatedAt: string
}): Phase1PilotManifest {
  const existingRows = input.phase1a.rows.filter((row) => row.wave === "pilot")
  const newRows = input.phase1b.rows.filter((row) => row.wave === "pilot")
  if (existingRows.length !== 20 || newRows.length !== 5)
    throw new Error(`phase1_pilot_product_count:${existingRows.length}:${newRows.length}`)
  const existing = existingRows
    .map((row) => ({
      product_id: row.product_id,
      category_key: row.category_key,
      identity: row.identity,
      packages: row.pilot_gtin_evidence?.packages ?? [],
    }))
    .sort((a, b) => a.product_id.localeCompare(b.product_id))
  const newest = newRows
    .map((row) => ({
      candidate_id: row.candidate_id,
      category_key: row.category_key,
      identity: row.identity,
      package: row.package,
      source_urls: row.sources.pdp_urls,
    }))
    .sort((a, b) => a.candidate_id.localeCompare(b.candidate_id))
  const existingGtins = existing.flatMap((row) => row.packages.map((item) => item.canonical_gtin14))
  const newGtins = newest.map((row) => row.package.canonical_gtin14)
  if (
    existingGtins.length !== 22 ||
    newGtins.some((gtin) => gtin === null) ||
    newGtins.length !== 5
  )
    throw new Error("phase1_pilot_gtin_evidence_incomplete")
  const combined = [...existingGtins, ...(newGtins as string[])]
  if (new Set(combined).size !== 27)
    throw new Error(`phase1_pilot_gtin_overlap:${combined.length}:${new Set(combined).size}`)
  const content = {
    schema_version: "scanner-phase1-pilot-manifest-v1" as const,
    source: {
      phase1a_content_fingerprint: input.phase1a.content_fingerprint,
      phase1b_content_fingerprint: input.phase1b.content_fingerprint,
      research_only: true as const,
      note: "This is an exact research-only pilot manifest. No product is catalog-intake-ready or scan-result-ready until full Product Intake evidence, classification, human review, an approved publish batch, and post-publish verification complete.",
    },
    totals: {
      existing_products: 20 as const,
      new_products: 5 as const,
      total_products: 25 as const,
      existing_canonical_gtins: 22 as const,
      new_canonical_gtins: 5 as const,
      unique_canonical_gtins: 27 as const,
    },
    existing,
    new: newest,
  }
  return { generated_at: input.generatedAt, ...content, content_fingerprint: fingerprint(content) }
}

function main() {
  const root = process.cwd()
  const file = (name: string) =>
    JSON.parse(readFileSync(join(root, "data/scanner-catalog-coverage/2026-08-26", name), "utf8"))
  const required = [
    "retailer-core-candidates.json",
    "retailer-specialist-candidates.json",
    "new-pilot-research.json",
    "phase1a-existing-ledger.json",
  ]
  if (
    required.some(
      (name) => !existsSync(join(root, "data/scanner-catalog-coverage/2026-08-26", name)),
    )
  )
    throw new Error("phase1b_inputs_missing")
  const generatedAt = new Date().toISOString()
  const ledger = buildPhase1bLedger({
    core: file("retailer-core-candidates.json"),
    specialist: file("retailer-specialist-candidates.json"),
    pilotResearch: file("new-pilot-research.json"),
    generatedAt,
  })
  const manifest = buildPilotManifest({
    phase1a: file("phase1a-existing-ledger.json"),
    phase1b: ledger,
    generatedAt,
  })
  writeFileSync(join(root, OUTPUT_PATH), `${JSON.stringify(ledger, null, 2)}\n`)
  writeFileSync(join(root, PILOT_OUTPUT_PATH), `${JSON.stringify(manifest, null, 2)}\n`)
  process.stdout.write(
    `${JSON.stringify({ ledger_path: OUTPUT_PATH, selected_products: ledger.rows.length, ledger_content_fingerprint: ledger.content_fingerprint, pilot_manifest_path: PILOT_OUTPUT_PATH, pilot_content_fingerprint: manifest.content_fingerprint })}\n`,
  )
}

if ((process.argv[1] ?? "").endsWith("build-phase1b-ledger.ts")) main()

import { createHash } from "node:crypto"
import { existsSync, readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"

import { canonicalizeGtin } from "../../src/lib/product-identity/normalize"

const DIRECTORY = "data/scanner-catalog-coverage/2026-08-26"
const LANES = ["A", "B", "C", "D"] as const
const LANE_CATEGORIES = {
  A: ["shampoo", "deep_cleansing_shampoo", "dry_shampoo"],
  B: ["conditioner"],
  C: ["leave_in", "bondbuilder"],
  D: ["mask", "oil"],
} as const
type Lane = (typeof LANES)[number]
type Json = Record<string, unknown>

function stable(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stable)
  if (value && typeof value === "object")
    return Object.fromEntries(
      Object.keys(value as Json)
        .sort()
        .map((key) => [key, stable((value as Json)[key])]),
    )
  return value
}
export function fingerprint(value: unknown) {
  return createHash("sha256")
    .update(JSON.stringify(stable(value)))
    .digest("hex")
}
function object(value: unknown, label: string): Json {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error(`research_batches_${label}_object_required`)
  return value as Json
}
function string(value: unknown, label: string): string {
  if (typeof value !== "string" || !value.trim())
    throw new Error(`research_batches_${label}_string_required`)
  return value
}
function number(value: unknown, label: string): number {
  if (!Number.isInteger(value) || (value as number) < 0)
    throw new Error(`research_batches_${label}_nonnegative_integer_required`)
  return value as number
}
function url(value: unknown, label: string): string {
  const result = string(value, label)
  try {
    const parsed = new URL(result)
    if (parsed.protocol !== "https:" && parsed.protocol !== "http:") throw new Error()
  } catch {
    throw new Error(`research_batches_${label}_direct_http_url_required`)
  }
  return result
}
function array(value: unknown, label: string): unknown[] {
  if (!Array.isArray(value)) throw new Error(`research_batches_${label}_array_required`)
  return value
}

export type VerifiedPackage = {
  raw_gtin: string
  canonical_gtin14: string
  size: string
  market_scope: string
  source_url: string
  source_urls: string[]
  source_checked_at: string
  exact_match_note: string
}
export type ResearchRow = {
  product_id: string
  expected_identity: { canonical_brand: string; clean_name: string; category_key: string }
  status: "verified" | "blocked"
  blocker: string | null
  evidence_checked_at: string
  evidence_attempted?: string[]
  packages: VerifiedPackage[]
}
export type LaneArtifact = {
  lane: Lane
  assignment_content_fingerprint: string
  content_fingerprint: string
  reconciliation: {
    assigned_products: number
    verified_products: number
    blocked_products: number
    verified_gtins: number
    by_category: Record<
      string,
      {
        assigned_products: number
        verified_products: number
        blocked_products: number
        verified_gtins: number
      }
    >
  }
  products: ResearchRow[]
}

export function validateLaneArtifact(raw: unknown, assignment: Json, lane: Lane): LaneArtifact {
  const artifact = object(raw, `lane_${lane}`)
  if (artifact.schema_version !== "scanner-existing-catalog-gtin-research-v1")
    throw new Error(`research_batches_lane_${lane}_schema_drift`)
  if (artifact.lane !== lane) throw new Error(`research_batches_lane_${lane}_name_drift`)
  if (artifact.assignment_content_fingerprint !== assignment.content_fingerprint)
    throw new Error(`research_batches_lane_${lane}_assignment_fingerprint_drift`)
  const {
    generated_at: _generatedAt,
    content_fingerprint: suppliedFingerprint,
    ...fingerprintContent
  } = artifact
  if (
    string(suppliedFingerprint, `lane_${lane}_content_fingerprint`) !==
    fingerprint(fingerprintContent)
  )
    throw new Error(`research_batches_lane_${lane}_content_fingerprint_drift`)
  const expectedRows = array(assignment.rows, `assignment_${lane}_rows`).map((value) =>
    object(value, `assignment_${lane}_row`),
  )
  const expected = new Map(
    expectedRows.map((row) => [string(row.product_id, `assignment_${lane}_product_id`), row]),
  )
  const rows = array(artifact.products, `lane_${lane}_products`).map((value) =>
    object(value, `lane_${lane}_product`),
  )
  if (rows.length !== expected.size)
    throw new Error(`research_batches_lane_${lane}_assigned_count_drift`)
  const seen = new Set<string>()
  let verified = 0
  let gtins = 0
  const parsed = rows.map((row): ResearchRow => {
    const productId = string(row.product_id, `lane_${lane}_product_id`)
    if (seen.has(productId) || !expected.has(productId))
      throw new Error(`research_batches_lane_${lane}_unknown_or_duplicate_product:${productId}`)
    seen.add(productId)
    const expectedRow = expected.get(productId)!
    const identity = object(row.expected_identity, `lane_${lane}_identity`)
    const expectedIdentity = object(expectedRow.identity, `assignment_${lane}_identity`)
    for (const field of ["canonical_brand", "clean_name"] as const)
      if (identity[field] !== expectedIdentity[field])
        throw new Error(`research_batches_lane_${lane}_identity_drift:${productId}`)
    const category = string(identity.category_key, `lane_${lane}_category`)
    if (category !== expectedRow.category_key || !LANE_CATEGORIES[lane].includes(category as never))
      throw new Error(`research_batches_lane_${lane}_category_drift:${productId}`)
    const status = string(row.status, `lane_${lane}_status`)
    const packages = array(row.packages, `lane_${lane}_packages`)
    const blocker = row.blocker === null ? null : string(row.blocker, `lane_${lane}_blocker`)
    const evidenceCheckedAt = string(row.evidence_checked_at, `lane_${lane}_evidence_checked_at`)
    if (status === "verified") {
      if (blocker !== null || packages.length === 0)
        throw new Error(`research_batches_lane_${lane}_verified_shape:${productId}`)
      verified++
    } else if (status === "blocked") {
      const attempted = array(row.evidence_attempted, `lane_${lane}_blocked_evidence`)
      if (!blocker || packages.length || !attempted.length)
        throw new Error(`research_batches_lane_${lane}_blocked_shape:${productId}`)
      attempted.forEach((item) => url(item, `lane_${lane}_blocked_source`))
    } else throw new Error(`research_batches_lane_${lane}_status_drift:${productId}`)
    const packageByCanonical = new Map<string, string>()
    const parsedPackages = packages.map((value): VerifiedPackage => {
      const pkg = object(value, `lane_${lane}_package`)
      const rawGtin = string(pkg.raw_gtin, `lane_${lane}_raw_gtin`)
      const canonical = string(pkg.canonical_gtin14, `lane_${lane}_canonical_gtin14`)
      if (canonicalizeGtin(rawGtin) !== canonical)
        throw new Error(`research_batches_lane_${lane}_invalid_gtin:${rawGtin}`)
      const sourceUrl = url(pkg.source_url, `lane_${lane}_source_url`)
      const sourceUrls = array(pkg.source_urls, `lane_${lane}_source_urls`).map((item) =>
        url(item, `lane_${lane}_source_urls`),
      )
      if (!sourceUrls.includes(sourceUrl))
        throw new Error(`research_batches_lane_${lane}_source_url_not_listed`)
      const parsedPackage = {
        raw_gtin: rawGtin,
        canonical_gtin14: canonical,
        size: string(pkg.size, `lane_${lane}_size`),
        market_scope: string(pkg.market_scope, `lane_${lane}_market_scope`),
        source_url: sourceUrl,
        source_urls: sourceUrls,
        source_checked_at: string(pkg.source_checked_at, `lane_${lane}_source_checked_at`),
        exact_match_note: string(pkg.exact_match_note, `lane_${lane}_note`),
      }
      const previous = packageByCanonical.get(canonical)
      const serialized = JSON.stringify(stable(parsedPackage))
      if (previous && previous !== serialized)
        throw new Error(`research_batches_lane_${lane}_duplicate_package_gtin:${canonical}`)
      if (!previous) {
        packageByCanonical.set(canonical, serialized)
        gtins++
      }
      return parsedPackage
    })
    return {
      product_id: productId,
      expected_identity: {
        canonical_brand: string(identity.canonical_brand, `lane_${lane}_brand`),
        clean_name: string(identity.clean_name, `lane_${lane}_name`),
        category_key: category,
      },
      status: status as ResearchRow["status"],
      blocker,
      evidence_checked_at: evidenceCheckedAt,
      evidence_attempted: row.evidence_attempted as string[] | undefined,
      packages: parsedPackages,
    }
  })
  const r = object(artifact.reconciliation, `lane_${lane}_reconciliation`)
  const expectedRecon = {
    assigned_products: parsed.length,
    verified_products: verified,
    blocked_products: parsed.length - verified,
    verified_gtins: gtins,
  }
  for (const [key, value] of Object.entries(expectedRecon))
    if (number(r[key], `lane_${lane}_${key}`) !== value)
      throw new Error(`research_batches_lane_${lane}_reconciliation_drift:${key}`)
  const expectedByCategory = Object.fromEntries(
    LANE_CATEGORIES[lane].map((category) => {
      const matching = parsed.filter((row) => row.expected_identity.category_key === category)
      return [
        category,
        {
          assigned_products: matching.length,
          verified_products: matching.filter((row) => row.status === "verified").length,
          blocked_products: matching.filter((row) => row.status === "blocked").length,
          verified_gtins: matching.reduce(
            (sum, row) => sum + new Set(row.packages.map((pkg) => pkg.canonical_gtin14)).size,
            0,
          ),
        },
      ]
    }),
  )
  if (
    JSON.stringify(stable(object(r.by_category, `lane_${lane}_by_category`))) !==
    JSON.stringify(stable(expectedByCategory))
  )
    throw new Error(`research_batches_lane_${lane}_by_category_drift`)
  return {
    lane,
    assignment_content_fingerprint: string(
      artifact.assignment_content_fingerprint,
      `lane_${lane}_fingerprint`,
    ),
    content_fingerprint: string(artifact.content_fingerprint, `lane_${lane}_content_fingerprint`),
    reconciliation: {
      ...expectedRecon,
      by_category: expectedByCategory,
    },
    products: parsed,
  }
}

function referenceOwnership(input: { baseline: Json; e1: Json; e2: Json }) {
  const result = new Map<string, string>()
  const add = (raw: unknown, productId: string) => {
    const canonical = canonicalizeGtin(typeof raw === "string" ? raw : "")
    if (!canonical) return
    const existing = result.get(canonical)
    if (existing && existing !== productId)
      throw new Error(`research_batches_reference_ownership_conflict:${canonical}`)
    result.set(canonical, productId)
  }
  for (const value of array(input.baseline.products, "baseline_products")) {
    const product = object(value, "baseline_product")
    const productId = string(product.product_id, "baseline_product_id")
    for (const value of array(product.identifiers, "baseline_identifiers"))
      add(object(value, "baseline_identifier").identifier_value, productId)
  }
  for (const manifest of [input.e1, input.e2])
    for (const value of array(manifest.items, "safe_manifest_items")) {
      const item = object(value, "safe_manifest_item")
      const productId = string(item.product_id, "safe_manifest_product_id")
      for (const value of array(item.identifiers, "safe_manifest_identifiers")) {
        const identifier = object(value, "safe_manifest_identifier")
        add(identifier.raw_gtin ?? identifier.value, productId)
      }
    }
  return result
}

function openSubmissionGtins(baseline: Json): Set<string> {
  const envelope = object(
    baseline.open_submission_identity_candidates,
    "baseline_open_submission_candidates",
  )
  return new Set(
    array(envelope.resolved_identity_candidates, "baseline_open_submission_rows")
      .map((value) => object(value, "baseline_open_submission_row"))
      .flatMap((row) =>
        Array.isArray(row.canonical_gtin14s) ? row.canonical_gtin14s : [row.canonical_gtin14],
      )
      .map((value) => canonicalizeGtin(typeof value === "string" ? value : ""))
      .filter((value): value is string => value !== null),
  )
}

export function buildExistingResearchBatches(input: {
  assignments: Record<Lane, Json>
  artifacts: Record<Lane, unknown>
  baseline: Json
  e1: Json
  e2: Json
  generatedAt: string
}) {
  const lanes = LANES.map((lane) =>
    validateLaneArtifact(input.artifacts[lane], input.assignments[lane], lane),
  )
  const allRows = lanes.flatMap((lane) => lane.products)
  if (allRows.length !== 150 || new Set(allRows.map((row) => row.product_id)).size !== 150)
    throw new Error("research_batches_full_assignment_drift")
  const knownOwnership = referenceOwnership(input)
  const pendingSubmissionGtins = openSubmissionGtins(input.baseline)
  const ownership = new Map<string, string>()
  for (const row of allRows)
    for (const pkg of row.packages) {
      const previous = ownership.get(pkg.canonical_gtin14)
      if (previous && previous !== row.product_id)
        throw new Error(`research_batches_duplicate_research_gtin:${pkg.canonical_gtin14}`)
      const known = knownOwnership.get(pkg.canonical_gtin14)
      if (known && known !== row.product_id)
        throw new Error(`research_batches_reference_ownership_conflict:${pkg.canonical_gtin14}`)
      if (pendingSubmissionGtins.has(pkg.canonical_gtin14))
        throw new Error(`research_batches_open_submission_overlap:${pkg.canonical_gtin14}`)
      ownership.set(pkg.canonical_gtin14, row.product_id)
    }
  const verified = allRows.filter((row) => row.status === "verified")
  const content = {
    schema_version: "scanner-existing-catalog-gtin-research-summary-v1",
    source: {
      lane_content_fingerprints: Object.fromEntries(
        lanes.map((lane) => [lane.lane, lane.content_fingerprint]),
      ),
      assignment_content_fingerprints: Object.fromEntries(
        lanes.map((lane) => [lane.lane, lane.assignment_content_fingerprint]),
      ),
    },
    reconciliation: {
      assigned_products: 150,
      verified_products: verified.length,
      blocked_products: 150 - verified.length,
      verified_gtins: [...ownership].length,
      by_lane: Object.fromEntries(lanes.map((lane) => [lane.lane, lane.reconciliation])),
    },
    products: allRows.sort((a, b) => a.product_id.localeCompare(b.product_id)),
  }
  const summary = {
    generated_at: input.generatedAt,
    ...content,
    content_fingerprint: fingerprint(content),
  }
  const candidates = verified
    .sort((a, b) => a.product_id.localeCompare(b.product_id))
    .reduce<ResearchRow[][]>((acc, row, index) => {
      const bucket = Math.floor(index / 20)
      ;(acc[bucket] ??= []).push(row)
      return acc
    }, [])
    .map((rows, index) => {
      const content = {
        schema_version: "scanner-existing-identifier-research-candidates-v1",
        batch: `E${index + 3}`,
        research_only: true,
        source_summary_content_fingerprint: summary.content_fingerprint,
        items: rows.map((row) => ({
          product_id: row.product_id,
          expected_product: {
            brand: row.expected_identity.canonical_brand,
            name: row.expected_identity.clean_name,
            category_key: row.expected_identity.category_key,
          },
          identifiers: row.packages,
        })),
      }
      return {
        generated_at: input.generatedAt,
        ...content,
        content_fingerprint: fingerprint(content),
      }
    })
  return { summary, candidates }
}

function main() {
  const read = (file: string) =>
    JSON.parse(readFileSync(join(process.cwd(), DIRECTORY, file), "utf8"))
  const assignments = Object.fromEntries(
    LANES.map((lane) => [lane, read(`existing-catalog-research-lane-${lane.toLowerCase()}.json`)]),
  ) as Record<Lane, Json>
  const artifacts = Object.fromEntries(
    LANES.map((lane) => {
      const file = `existing-catalog-gtin-research-lane-${lane.toLowerCase()}-v1.json`
      if (!existsSync(join(process.cwd(), DIRECTORY, file)))
        throw new Error(`research_batches_missing_${lane}`)
      return [lane, read(file)]
    }),
  ) as Record<Lane, unknown>
  const result = buildExistingResearchBatches({
    assignments,
    artifacts,
    baseline: read("live-baseline.json"),
    e1: read("phase1-existing-identifier-backfill-e1-v1.json"),
    e2: read("phase1-existing-identifier-backfill-e2-v1.json"),
    generatedAt: new Date().toISOString(),
  })
  writeFileSync(
    join(process.cwd(), DIRECTORY, "existing-catalog-gtin-research-summary.json"),
    JSON.stringify(result.summary, null, 2) + "\n",
  )
  for (const candidate of result.candidates)
    writeFileSync(
      join(
        process.cwd(),
        DIRECTORY,
        `phase1-existing-identifier-backfill-e${candidate.batch.slice(1)}-candidates-v1.json`,
      ),
      JSON.stringify(candidate, null, 2) + "\n",
    )
  process.stdout.write(
    JSON.stringify({
      summary: result.summary.content_fingerprint,
      candidates: result.candidates.map((candidate) => candidate.content_fingerprint),
    }) + "\n",
  )
}
if ((process.argv[1] ?? "").endsWith("build-existing-research-batches.ts")) main()

import { createHash } from "node:crypto"
import { existsSync, mkdirSync, writeFileSync } from "node:fs"
import { dirname, join, sep } from "node:path"

import { config as loadEnv } from "dotenv"
import { createClient, type SupabaseClient } from "@supabase/supabase-js"

import { canonicalizeGtin } from "../../src/lib/product-identity/normalize"
import { loadScanProductFacts } from "../../src/lib/personal-plan/products/authority/catalog-facts"
import type { PersonalPlanCategory } from "../../src/lib/personal-plan/products/contracts"
import { evaluateScanCatalogReadiness } from "../../src/lib/product-intake/scan-catalog-readiness"

const OUTPUT_PATH = "data/scanner-catalog-coverage/2026-08-26/readiness-baseline.json"
const PAGE_SIZE = 500
const BARCODE_TYPES = new Set(["ean", "gtin", "barcode"])
const SUPPORTED_CATEGORIES = new Set<PersonalPlanCategory>([
  "shampoo",
  "conditioner",
  "mask",
  "leave_in",
  "oil",
  "dry_shampoo",
  "heat_protectant",
  "deep_cleansing_shampoo",
  "scalp_care",
  "bondbuilder",
])

type Row = Record<string, unknown>
type Blocker =
  | "has_disposition"
  | "missing_presentation_image"
  | "missing_product_facts"
  | "missing_required_protocol"
  | "verdict_unknown"
  | "verdict_error"

export type ReadinessCandidate = {
  product_id: string
  category: PersonalPlanCategory
  has_barcode: false
  status: "ready_for_ean_research" | "blocked"
  blockers: Blocker[]
  verdicts: Array<{
    profile: "fine" | "normal" | "coarse"
    role: string
    verdict: "ideal" | "supportive" | "mismatch" | "unknown" | "error"
  }>
}

export type ReadinessProductAudit = {
  product_id: string
  category: PersonalPlanCategory
  has_barcode: boolean
  status: "scan_result_ready" | "ready_for_ean_research" | "blocked"
  blockers: Blocker[]
  verdicts: ReadinessCandidate["verdicts"]
}

export type ReadinessBaseline = {
  schema_version: 2
  exported_at: string
  source: {
    project_ref: string
    read_only: true
    identifier_canonicalization: "runtime_canonicalize_gtin14"
  }
  reconciliation: {
    active_supported_without_barcode: number
    ready_for_ean_research: number
    blocked: number
    by_category: Record<
      string,
      { candidates: number; ready_for_ean_research: number; blocked: number }
    >
  }
  full_catalog_reconciliation: {
    active_supported: number
    barcode_linked: number
    scan_result_ready: number
    ready_for_ean_research: number
    blocked: number
    by_category: Record<
      string,
      {
        products: number
        barcode_linked: number
        scan_result_ready: number
        ready_for_ean_research: number
        blocked: number
      }
    >
  }
  candidates: ReadinessCandidate[]
  products: ReadinessProductAudit[]
  content_fingerprint: string
}

function text(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value : null
}
function stable(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stable)
  if (value && typeof value === "object")
    return Object.fromEntries(
      Object.keys(value as Row)
        .sort()
        .map((key) => [key, stable((value as Row)[key])]),
    )
  return value
}
export function fingerprint(
  value: Omit<ReadinessBaseline, "exported_at" | "content_fingerprint">,
): string {
  return createHash("sha256")
    .update(JSON.stringify(stable(value)))
    .digest("hex")
}

/** A conservative pure seam: identity alone never bypasses the verdict-readiness oracle. */
export function classifyProductReadiness(
  input: Omit<ReadinessProductAudit, "status" | "blockers"> & {
    has_disposition: boolean
    image_url_present: boolean
    product_facts_present: boolean
    required_protocols_complete: boolean
  },
): ReadinessProductAudit {
  const blockers: Blocker[] = []
  if (input.has_disposition) blockers.push("has_disposition")
  if (!input.image_url_present) blockers.push("missing_presentation_image")
  if (!input.product_facts_present) blockers.push("missing_product_facts")
  if (!input.required_protocols_complete) blockers.push("missing_required_protocol")
  if (input.verdicts.some((item) => item.verdict === "unknown")) blockers.push("verdict_unknown")
  if (input.verdicts.some((item) => item.verdict === "error")) blockers.push("verdict_error")
  return {
    product_id: input.product_id,
    category: input.category,
    has_barcode: input.has_barcode,
    status:
      blockers.length > 0
        ? "blocked"
        : input.has_barcode
          ? "scan_result_ready"
          : "ready_for_ean_research",
    blockers,
    verdicts: [...input.verdicts].sort((a, b) =>
      `${a.profile}\u0000${a.role}`.localeCompare(`${b.profile}\u0000${b.role}`),
    ),
  }
}

/** Compatibility projection for the existing unlinked-product ledger. */
export function classifyCandidate(
  input: Omit<ReadinessCandidate, "status" | "blockers"> & {
    has_disposition: boolean
    image_url_present: boolean
    product_facts_present: boolean
    required_protocols_complete: boolean
  },
): ReadinessCandidate {
  const result = classifyProductReadiness(input)
  return {
    ...result,
    has_barcode: false,
    status: result.status === "blocked" ? "blocked" : "ready_for_ean_research",
  }
}

export function selectActiveSupportedProducts(products: Row[], identifiers: Row[]) {
  const barcodeProductIds = new Set(
    identifiers
      .filter(
        (row) =>
          BARCODE_TYPES.has(text(row.identifier_type) ?? "") &&
          canonicalizeGtin(text(row.identifier_value) ?? "") !== null,
      )
      .map((row) => String(row.product_id)),
  )
  return products
    .filter(
      (product) =>
        product.is_active === true &&
        text(product.lifecycle_status) === "active" &&
        SUPPORTED_CATEGORIES.has(text(product.category_key) as PersonalPlanCategory),
    )
    .map((row) => ({ row, has_barcode: barcodeProductIds.has(String(row.id)) }))
}

export async function buildReadinessBaseline(input: {
  client: SupabaseClient
  products: Row[]
  identifiers: Row[]
  dispositions: Row[]
  exportedAt: string
  projectRef: string
}): Promise<ReadinessBaseline> {
  const dispositionProductIds = new Set(input.dispositions.map((row) => String(row.product_id)))
  const sourceProducts = selectActiveSupportedProducts(input.products, input.identifiers)
  const products = await mapWithConcurrency(sourceProducts, 8, async ({ row, has_barcode }) => {
    const category = text(row.category_key) as PersonalPlanCategory
    const productId = String(row.id)
    const evaluated = await evaluateScanCatalogReadiness({
      category,
      productId,
      loadFacts: (targetCategory, targetProductId, selectionContext) =>
        loadScanProductFacts(input.client, targetCategory, targetProductId, selectionContext),
    })
    return classifyProductReadiness({
      product_id: productId,
      category,
      has_barcode,
      has_disposition: dispositionProductIds.has(productId),
      image_url_present: text(row.image_url) !== null,
      product_facts_present: evaluated.factsPresent,
      required_protocols_complete: evaluated.protocolsComplete,
      verdicts: evaluated.verdicts,
    })
  })
  products.sort((a, b) =>
    `${a.category}\u0000${a.product_id}`.localeCompare(`${b.category}\u0000${b.product_id}`),
  )
  const candidates = products
    .filter((item): item is ReadinessProductAudit & { has_barcode: false } => !item.has_barcode)
    .map(
      (item): ReadinessCandidate => ({
        ...item,
        has_barcode: false,
        status: item.status === "blocked" ? "blocked" : "ready_for_ean_research",
      }),
    )
  candidates.sort((a, b) =>
    `${a.category}\u0000${a.product_id}`.localeCompare(`${b.category}\u0000${b.product_id}`),
  )
  const by_category: ReadinessBaseline["reconciliation"]["by_category"] = {}
  for (const item of candidates) {
    const bucket = by_category[item.category] ?? {
      candidates: 0,
      ready_for_ean_research: 0,
      blocked: 0,
    }
    bucket.candidates++
    bucket[item.status]++
    by_category[item.category] = bucket
  }
  const full_by_category: ReadinessBaseline["full_catalog_reconciliation"]["by_category"] = {}
  for (const item of products) {
    const bucket = full_by_category[item.category] ?? {
      products: 0,
      barcode_linked: 0,
      scan_result_ready: 0,
      ready_for_ean_research: 0,
      blocked: 0,
    }
    bucket.products++
    if (item.has_barcode) bucket.barcode_linked++
    bucket[item.status]++
    full_by_category[item.category] = bucket
  }
  const content = {
    schema_version: 2 as const,
    source: {
      project_ref: input.projectRef,
      read_only: true as const,
      identifier_canonicalization: "runtime_canonicalize_gtin14" as const,
    },
    reconciliation: {
      active_supported_without_barcode: candidates.length,
      ready_for_ean_research: candidates.filter((item) => item.status === "ready_for_ean_research")
        .length,
      blocked: candidates.filter((item) => item.status === "blocked").length,
      by_category: Object.fromEntries(
        Object.entries(by_category).sort(([a], [b]) => a.localeCompare(b)),
      ),
    },
    full_catalog_reconciliation: {
      active_supported: products.length,
      barcode_linked: products.filter((item) => item.has_barcode).length,
      scan_result_ready: products.filter((item) => item.status === "scan_result_ready").length,
      ready_for_ean_research: products.filter((item) => item.status === "ready_for_ean_research")
        .length,
      blocked: products.filter((item) => item.status === "blocked").length,
      by_category: Object.fromEntries(
        Object.entries(full_by_category).sort(([a], [b]) => a.localeCompare(b)),
      ),
    },
    candidates,
    products,
  }
  return { exported_at: input.exportedAt, ...content, content_fingerprint: fingerprint(content) }
}

async function mapWithConcurrency<T, Result>(
  values: T[],
  limit: number,
  mapper: (value: T) => Promise<Result>,
): Promise<Result[]> {
  const results = new Array<Result>(values.length)
  let cursor = 0
  await Promise.all(
    Array.from({ length: Math.min(limit, values.length) }, async () => {
      for (;;) {
        const index = cursor++
        if (index >= values.length) return
        results[index] = await mapper(values[index]!)
      }
    }),
  )
  return results
}

function loadLocalEnv() {
  const cwd = process.cwd()
  const root = cwd.includes(`${sep}.worktrees${sep}`)
    ? cwd.slice(0, cwd.indexOf(`${sep}.worktrees${sep}`))
    : cwd
  for (const path of [join(root, ".env.local"), join(cwd, ".env.local")])
    if (existsSync(path)) loadEnv({ path, override: false })
}
async function readAll(
  client: SupabaseClient,
  table: string,
  columns: string,
  orderBy: string,
): Promise<Row[]> {
  const rows: Row[] = []
  for (let from = 0; ; from += PAGE_SIZE) {
    const { data, error } = await client
      .from(table)
      .select(columns)
      .order(orderBy, { ascending: true })
      .range(from, from + PAGE_SIZE - 1)
    if (error) throw new Error(`readiness_read_failed:${table}:${error.message}`)
    rows.push(...((data ?? []) as unknown as Row[]))
    if ((data ?? []).length < PAGE_SIZE) return rows
  }
}
async function main() {
